{const ix=document.querySelector("#index ol.index");ix.innerHTML="<li data-sec="explorer" class=""><a class="sec" href="#explorer">The Explorer<span class="count">37</span></a><ol class="entries"><li data-for="explorer-number"><a href="#explorer-number">i · A world from a number</a></li><li data-for="explorer-land"><a href="#explorer-land">ii · The Land</a></li><li data-for="explorer-strand"><a href="#explorer-strand">iii · The Strand</a></li><li data-for="explorer-hand"><a href="#explorer-hand">iv · The Hand</a></li><li data-for="explorer-glass"><a href="#explorer-glass">v · The Surveyor's Glass</a></li><li data-for="explorer-places"><a href="#explorer-places">vi · Places on the chart</a></li><li data-for="explorer-press"><a href="#explorer-press">vii · The Press</a></li><li data-for="explorer-table"><a href="#explorer-table">viii · The Chart Table</a></li></ol></li><li data-sec="prospect" class="sub"><a class="sec" href="#prospect">The Prospect<span class="count">5</span></a><ol class="entries"><li data-for="prospect-plate"><a href="#prospect-plate">i · A town, engraved</a></li></ol></li><li data-sec="ribbon" class="sub"><a class="sec" href="#ribbon">The Wayfarer's Ribbon<span class="count">6</span></a><ol class="entries"><li data-for="ribbon-road"><a href="#ribbon-road">i · A road, unrolled</a></li></ol></li><li data-sec="explorer-portfolio" class="sub"><a class="sec" href="#explorer-portfolio">The Portfolio<span class="count">6</span></a><ol class="entries"><li data-for="explorer-portfolio-gather"><a href="#explorer-portfolio-gather">i · Gather, then take home</a></li></ol></li><li data-sec="writing-room" class=""><a class="sec" href="#writing-room">The Writing Room<span class="count">6</span></a><ol class="entries"><li data-for="writing-room-found"><a href="#writing-room-found">i · A world from a sentence</a></li></ol></li><li data-sec="reading-room" class=""><a class="sec" href="#reading-room">The Reading Room<span class="count">6</span></a><ol class="entries"><li data-for="reading-room-watch"><a href="#reading-room-watch">i · Watch a world live</a></li></ol></li><li data-sec="print-room" class=""><a class="sec" href="#print-room">The Print Room<span class="count">8</span></a><ol class="entries"><li data-for="print-room-proof"><a href="#print-room-proof">i · A proof on the desk</a></li><li data-for="print-room-atlas"><a href="#print-room-atlas">ii · The Bound Atlas</a></li><li data-for="print-room-posters"><a href="#print-room-posters">iii · Posters</a></li></ol></li><li data-sec="seed-of-the-day" class=""><a class="sec" href="#seed-of-the-day">The Seed of the Day<span class="count">5</span></a><ol class="entries"><li data-for="seed-of-the-day-hunt"><a href="#seed-of-the-day-hunt">i · The Daily Hunt</a></li></ol></li><li data-sec="gallery" class=""><a class="sec" href="#gallery">The Gallery<span class="count">2</span></a><ol class="entries"><li data-for="gallery-browse"><a href="#gallery-browse">i · Worlds hung for viewing</a></li></ol></li><li data-sec="afterward" class="lean"><a class="sec" href="#afterward">When the steps are done</a></li>";const w=document.querySelector("#index .card-where");if(w)w.textContent="the room you are reading is inked";
