><li data-for="reading-room-watch"><a href="#reading-room-watch">i · Watch a world live</a></li></ol></li><li data-sec="print-room" class=""><a class="sec" href="#print-room">The Print Room<span class="count">8</span></a><ol class="entries"><li data-for="print-room-proof"><a href="#print-room-proof">i · A proof on the desk</a></li><li data-for="print-room-atlas"><a href="#print-room-atlas">ii · The Bound Atlas</a></li><li data-for="print-room-posters"><a href="#print-room-posters">iii · Posters</a></li></ol></li><li data-sec="seed-of-the-day" class=""><a class="sec" href="#seed-of-the-day">The Seed of the Day<span class="count">5</span></a><ol class="entries"><li data-for="seed-of-the-day-hunt"><a href="#seed-of-the-day-hunt">i · The Daily Hunt</a></li></ol></li><li data-sec="gallery" class=""><a class="sec" href="#gallery">The Gallery<span class="count">2</span></a><ol class="entries"><li data-for="gallery-browse"><a href="#gallery-browse">i · Worlds hung for viewing</a></li></ol></li><li data-sec="afterward" class="lean"><a class="sec" href="#afterward">When the steps are done</a></li>";const w=document.querySelector("#index .card-where");if(w)w.textContent="the room you are reading is inked";
