t x="275.1" y="200.20000000000002">vii</text></g><g class="col-way"><circle cx="278.3" cy="183.5" r="5.4"/><text x="278.3" y="185.8">viii</text></g><g class="col-way"><circle cx="214" cy="166" r="5.4"/><text x="214" y="168.3">i</text></g><g class="col-way"><circle cx="126" cy="254" r="5.4"/><text x="126" y="256.3">i</text></g><g class="col-way"><circle cx="368" cy="154" r="5.4"/><text x="368" y="156.3">i</text></g><g class="col-way"><circle cx="400" cy="178" r="5.4"/><text x="400" y="180.3">i</text></g><g class="col-way"><circle cx="272" cy="292" r="5.4"/><text x="272" y="294.3">i</text></g><g class="col-way"><circle cx="433.6" cy="223" r="5.4"/><text x="433.6" y="225.3">i</text></g><g class="col-way"><circle cx="418" cy="250" r="5.4"/><text x="418" y="252.3">ii</text></g><g class="col-way"><circle cx="402.4" cy="223" r="5.4"/><text x="402.4" y="225.3">iii</text></g><g class="col-way"><circle cx="486" cy="114" r="5.4"/><text x="486" y="116.3">i</text></g><g class="col-way"><circle cx="500" cy="338" r="5.4"/><text x="500" y="340.3">i</text></g><text class="col-lean" x="158" y="344">lean on it afterwards</text><text class="col-lean" x="352" y="350">lean on it afterwards</text><g class="col-you"><circle cx="300" cy="196" r="31"/><text x="300" y="240">you are here: ii · The Land</text></g>
